/**
 * Round-trip edge case for window functions: a SELECT using every {@code winf:} function, every frame-bound spelling,
 * expression partition keys and mixed-direction multi-key ordering renders back to SPARQL text that re-parses to the
 * same window algebra, evaluates identically and renders identically again.
 */
class WindowFunctionRenderingEdgeCaseTest {

	private static final String PREFIX = "PREFIX winf:<http://rdf4j.org/function/window#> ";

	private static final String EVERY_FUNCTION = "SELECT ?p ?x"
			+ " (winf:rowNumber(winf:partitionBy(?p), winf:orderBy(?x)) AS ?rn)"
			+ " (winf:rank(winf:partitionBy(?p), winf:orderBy(winf:desc(?x))) AS ?rk)"
			+ " (winf:denseRank(winf:orderBy(?x)) AS ?dr)"
			+ " (winf:ntile(2, winf:orderBy(?x)) AS ?tile)"
			+ " (winf:lag(?x, 2, -1, winf:partitionBy(?p), winf:orderBy(?x)) AS ?lag)"
			+ " (winf:lead(?x, winf:orderBy(?x)) AS ?lead)"
			+ " (winf:firstValue(?x, winf:orderBy(?x), winf:rows(\"unbounded preceding\", \"current row\")) AS ?first)"
			+ " (winf:lastValue(?x, winf:orderBy(?x), winf:rows(\"current\", \"unbounded following\")) AS ?last)"
			+ " (winf:nthValue(?x, 2, winf:orderBy(?x), winf:range(\"unbounded\", \"unbounded\")) AS ?nth)"
			+ " (winf:percentRank(winf:orderBy(?x)) AS ?pr)"
			+ " (winf:cumeDist(winf:orderBy(?x)) AS ?cd)"
			+ " (winf:sum(?x, winf:partitionBy(?p * 2), winf:orderBy(?x), winf:rows(-2, 0)) AS ?sum)"
			+ " (winf:avg(?x, winf:orderBy(?x), winf:rows(-1, 1)) AS ?avg)"
			+ " (winf:count(?x) AS ?cnt)"
			+ " (winf:min(?x, winf:orderBy(winf:desc(?p), winf:asc(?x), ?p + ?x)) AS ?min)"
			+ " (winf:max(?x, winf:partitionBy(?p), winf:range(\"current\", \"unbounded\")) AS ?max)"
			+ " WHERE { VALUES (?p ?x) { (1 3) (1 1) (2 2) (2 5) (1 4) } } ORDER BY ?p ?x";

	@Test
	void everyWindowFunctionAndFrameSpellingRoundTrips() {
		List<Executable> cases = new ArrayList<>();
		for (boolean legacy : List.of(false, true)) {
			cases.add(() -> {
				ParsedQuery original = parse(EVERY_FUNCTION);
				TupleExpr snapshot = original.getTupleExpr().clone();
				List<Map<String, Value>> expected = evaluate(original.getTupleExpr().clone());
				assertThat(expected).hasSize(5);
				String rendered = render(original, legacy);
				String context = (legacy ? "legacy" : "IR") + " renderer\n" + rendered;
				ParsedQuery reparsed = QueryParserUtil.parseQuery(QueryLanguage.SPARQL, rendered, null);
				// same window algebra: every function, its arguments, partition keys, order keys and frame
				List<WindowFunctionCall> before = windows(original.getTupleExpr());
				assertThat(before).as(context).hasSize(16);
				assertThat(windows(reparsed.getTupleExpr())).as(context).containsExactlyElementsOf(before);
				// same rows
				assertThat(evaluate(reparsed.getTupleExpr())).as(context).containsExactlyElementsOf(expected);
				// rendering is idempotent and does not mutate its input
				assertThat(render(reparsed, legacy)).as(context + " re-render").isEqualTo(rendered);
				assertThat(original.getTupleExpr()).as(context + " source algebra").isEqualTo(snapshot);
			});
		}
		assertAll(cases);
	}

	private static ParsedQuery parse(String query) {
		return QueryParserUtil.parseQuery(QueryLanguage.SPARQL, PREFIX + query, null);
	}

	private static String render(ParsedQuery query, boolean legacy) throws Exception {
		if (legacy) {
			return new SPARQLQueryRenderer().render(query, QueryParseOptions.DEFAULT);
		}
		Config config = new Config();
		config.parseOptions = QueryParseOptions.DEFAULT;
		return new TupleExprIRRenderer(config).render(query.getTupleExpr(), null);
	}

	private static List<WindowFunctionCall> windows(TupleExpr expression) {
		List<WindowFunctionCall> windows = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(WindowFunctionCall call) {
				windows.add(call);
				super.meet(call);
			}
		});
		return windows;
	}

	private static List<Map<String, Value>> evaluate(TupleExpr expression) {
		TripleSource source = new TripleSource() {
			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
					Resource... contexts) {
				return new EmptyIteration<>();
			}

			@Override
			public ValueFactory getValueFactory() {
				return SimpleValueFactory.getInstance();
			}
		};
		List<Map<String, Value>> rows = new ArrayList<>();
		try (CloseableIteration<BindingSet> result = new DefaultEvaluationStrategy(source, null)
				.precompile(expression)
				.evaluate(EmptyBindingSet.getInstance())) {
			while (result.hasNext()) {
				BindingSet bindings = result.next();
				Map<String, Value> row = new TreeMap<>();
				for (String name : bindings.getBindingNames()) {
					row.put(name, bindings.getValue(name));
				}
				rows.add(row);
			}
		}
		return rows;
	}
}
